using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.World;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RegionalRouteTests
{
    static WorldSession New()=>new(RegionalRoute.Create());
    static long Duration(ContractWorld w)=>RouteContract.Travel(0,RouteContract.Total(w),false,w);
    static void Send(WorldSession s){Assert.Equal(ResultCode.Accepted,s.Submit(RegionalRoute.Order(s.DiagnosticSnapshot(),"request:move"),s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.Submit(RegionalRoute.Order(s.DiagnosticSnapshot(),"request:delegate",ActionKind.Transfer,ContractFixture.Clerk),s.Revision).Code);}
    [Fact] public void ThreeRealAnchorsAndNewScenarioAreExplicit(){var w=RegionalRoute.Create();Assert.Equal(3,w.Definitions.Sites.Length);Assert.Equal(new[]{"清洲城","熱田神宮","善照寺砦"},w.Definitions.Sites.Select(s=>s.Name));Assert.Equal(RegionalRoute.Ruleset,w.Definitions.Ruleset);Assert.NotEqual(RouteContract.Version,w.Definitions.Version);Assert.NotEqual(RouteContract.Create().WorldId,w.WorldId);Assert.All(RegionalRoute.Catalog.Stops,s=>Assert.True(long.Parse(s.Revision)>0));}
    [Fact] public void GreatCircleLengthIsIndependentOfDisplayProjection(){var c=RegionalRoute.Catalog;for(int i=0;i<2;i++){var a=c.Stops[i];var b=c.Stops[i+1];double rad=Math.PI/180,lat=a.LatitudeE7/1e7*rad,lat2=b.LatitudeE7/1e7*rad,dlon=(b.LongitudeE7-a.LongitudeE7)/1e7*rad;var h=Math.Pow(Math.Sin((lat2-lat)/2),2)+Math.Cos(lat)*Math.Cos(lat2)*Math.Pow(Math.Sin(dlon/2),2);long length=(long)Math.Round(2.0*6371000*1000*Math.Asin(Math.Sqrt(h)));Assert.InRange(Math.Abs(length-c.LegLengthsMm[i]),0,1);}Assert.Equal(18337692,RouteContract.Total(RegionalRoute.Create()));}
    [Fact] public void PointMatchesNationalCoordinatesAtEveryAnchor(){var w=RegionalRoute.Create();long d=0;for(int i=0;i<3;i++){var s=RegionalRoute.Catalog.Stops[i];var p=JapanGeography.Project(new(s.LatitudeE7,s.LongitudeE7));Assert.Equal(new RoutePoint(p.EastMm,p.NorthMm),RouteContract.Point(d,w));if(i<2)d+=RegionalRoute.Legs[i].LengthMm;}}
    [Fact] public void RegionalDurationUsesPerLegCeilingAndNoEarlyArrival(){var s=New();Send(s);var w=s.DiagnosticSnapshot();Assert.Equal(18339,Duration(w));s.AdvanceTo(18339);Assert.True(s.GetRouteActorView(ContractFixture.Officer).Walking);s.AdvanceTo(18340);Assert.Equal(ContractFixture.Village,s.GetActorView(ContractFixture.Officer).Location.Site);}
    [Fact] public void TurningWaypointDoesNotSkipLastFractionOfLeg(){var w=RegionalRoute.Create();var length=RegionalRoute.Legs[0].LengthMm;Assert.Equal(length-560,RouteContract.DistanceAt(11654,w));Assert.Equal(length,RouteContract.DistanceAt(11655,w));Assert.Equal(1,RouteContract.Segment(length,w));Assert.Equal(length+1000,RouteContract.DistanceAt(11656,w));}
    [Fact] public void DelegationAndReportRemainIndependentOfPhysicalMovement(){var s=New();Send(s);s.AdvanceTo(6);Assert.True(s.GetRouteActorView(ContractFixture.Officer).Walking);Assert.Equal(40,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==ContractFixture.Treasury).Quantity);Assert.Equal(1,s.GetActorView(ContractFixture.Lord).Tasks.Count(t=>t.KnownStatus=="任務完了"));s.AdvanceTo(27509);Assert.Contains(s.GetActorView(ContractFixture.Lord).Tasks,t=>t.KnownStatus.Contains("結果未確認"));s.AdvanceTo(27510);Assert.Equal(2,s.GetActorView(ContractFixture.Lord).Tasks.Count(t=>t.KnownStatus=="任務完了"));}
    [Fact] public void RegionalAndLegacyObserversCannotBeMixed(){var s=New();Send(s);s.AdvanceTo(1001);Assert.NotEqual(RouteContract.Point(100000),s.GetRouteActorView(ContractFixture.Officer).Position);var legacy=RouteContract.Create();legacy.Definitions=legacy.Definitions with{Ruleset=RegionalRoute.Ruleset};Assert.Throws<InvalidDataException>(()=>new WorldSession(legacy));}
    [Theory][InlineData(1)][InlineData(2)] public void ForgedTimingIsRejected(int kind){var s=New();var i=RegionalRoute.Order(s.DiagnosticSnapshot(),"request:move");Assert.Equal(ResultCode.InvalidInput,s.Submit(kind==1?i with{WorkSeconds=4}:i with{DeliverySeconds=99},s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().Tasks);}
    [Fact] public void ChangedCoordinateCannotReuseCatalogVersion(){var w=RegionalRoute.Create();w.Definitions=w.Definitions with{Sites=w.Definitions.Sites.Select((s,i)=>i==0?s with{LatitudeE7=s.LatitudeE7+1}:s).ToArray()};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact] public void ArrivalCannotTeleportBackToOriginOnAnotherOrder(){var s=New();Send(s);s.AdvanceTo(18340);var before=s.GetRouteActorView(ContractFixture.Officer).Position;Assert.Equal(ResultCode.InvalidInput,s.Submit(RegionalRoute.Order(s.DiagnosticSnapshot(),"request:again"),s.Revision).Code);Assert.Equal(before,s.GetRouteActorView(ContractFixture.Officer).Position);}
    [Fact] public void IssuerViewNeverAcquiresSubordinateLivePosition(){var s=New();Send(s);s.AdvanceTo(1001);var p=s.GetRouteActorView(ContractFixture.Lord).Position;s.AdvanceTo(12000);Assert.Equal(p,s.GetRouteActorView(ContractFixture.Lord).Position);Assert.NotEqual(p,s.GetRouteActorView(ContractFixture.Officer).Position);}
    [Theory][InlineData(1001)][InlineData(11656)][InlineData(12656)][InlineData(18340)]
    public void SavedStagesRestoreAndContinueWithoutDoubleEffects(long at){var s=New();Send(s);s.AdvanceTo(at);var root=Path.Combine(Path.GetTempPath(),"hakutai-regional-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,RegionalRoute.Create().Definitions);store.Save(s,"test",s.DiagnosticSnapshot().WorldId,new(.375,60));var load=store.Prepare("test");var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(load,host.Current,host.Current.Revision));Assert.True(host.Current.Paused);Assert.Equal(s.GetRouteActorView(ContractFixture.Officer).Position,host.Current.GetRouteActorView(ContractFixture.Officer).Position);Assert.Equal(.375,load.Presentation.DisplayFraction);host.Current.SetPaused(false);s.AdvanceTo(27510);host.Current.AdvanceTo(27510);var a=s.DiagnosticSnapshot();var b=host.Current.DiagnosticSnapshot();Assert.Equal(a.Locations.Select(l=>l with{Revision=0}),b.Locations.Select(l=>l with{Revision=0}));Assert.Equal(a.EffectLedger,b.EffectLedger);Assert.Equal(a.Transfers,b.Transfers);Assert.Equal(a.Messaging.Messages,b.Messaging.Messages);Assert.Equal(ResultCode.AlreadyAccepted,host.Current.Submit(b.Requests.Single(r=>r.Id==new EntityId("request:move")).Intent,host.Current.Revision).Code);}
    [Fact] public void OtherScenarioAndChangedDependencyCannotLoadRegionalSave(){var s=New();Send(s);s.AdvanceTo(1001);var root=Path.Combine(Path.GetTempPath(),"hakutai-regional-deps-"+Guid.NewGuid().ToString("N"));new GenerationSaveStore(root,RegionalRoute.Create().Definitions).Save(s,"test",s.DiagnosticSnapshot().WorldId,new(0,1));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,RouteContract.Create().Definitions).Prepare("test"));Assert.Throws<ContractLoadException>(()=>new GenerationSaveStore(root,RegionalRoute.Create().Definitions with{Version="changed"}).Prepare("test"));}
    [Fact] public void ProjectionReadsDoNotDrawRandomnessOrChangeSimulation(){var s=New();Send(s);s.AdvanceTo(1001);var before=ContractJson.Write(s.DiagnosticSnapshot());for(int i=0;i<30;i++){s.GetRouteActorView(ContractFixture.Officer);s.GetRouteActorView(ContractFixture.Lord);}Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
}
